	const uint32_t j1 = i1 - (uint32_t)(((int32_t)width[1] - (int32_t)width0[1]) * 131072);
	uint32_t p0 = phase[0];
	uint32_t p1 = phase[1];
	uint32_t q0 = p0 - ((uint32_t)width0[0] << 22);
	uint32_t q1 = p1 - ((uint32_t)width0[1] << 22);
